-- cdk_work_in_process (work-in-process) -- Work In Process
-- WIP Schedule
-- SAP analogue: Anlagen im Bau (AIB) suspense-account analogue / CO-PA WIP settlement (conceptual analogue only)
-- grain: one row per RO per WIP snapshot date
-- api reach: partial
-- generated by schema/bin/gen_ddl.py from contract EgD-CDK-FIELDS-v2 -- do not hand-edit, regenerate instead

CREATE TABLE IF NOT EXISTS cdk_work_in_process (
    wip_snapshot_date date,
    ro_number varchar(20) NOT NULL,
    wip_status varchar(32) NOT NULL,
    wip_labor_amount numeric(13,2),
    wip_parts_amount numeric(13,2),
    wip_opened_date date,
    wip_age_days numeric(13,3),
    wip_closed_date date,
    wip_gl_account varchar(10),
    wip_department_suffix varchar(4),
    _rooftop_id varchar(20),
    _extracted_at timestamptz,
    _source_route varchar(16),
    _batch_id varchar(64),
    PRIMARY KEY (wip_snapshot_date, ro_number)
);

