-- Column comments (dealer-language label + confidence mark: [D]=documented [I]=inferred [U]=unverified)
COMMENT ON COLUMN cdk_work_in_process.wip_snapshot_date IS '[I] the date this work-in-process balance was captured';
COMMENT ON COLUMN cdk_work_in_process.ro_number IS '[D] Associated RO Number';
COMMENT ON COLUMN cdk_work_in_process.wip_status IS '[D] WIP Status (values: OPENED=RO opened within the WIP window (past 48h); VOIDED=RO voided within the WIP window; CLOSED=RO closed within the WIP window)';
COMMENT ON COLUMN cdk_work_in_process.wip_labor_amount IS '[I] WIP Labor Amount (suspense)';
COMMENT ON COLUMN cdk_work_in_process.wip_parts_amount IS '[I] WIP Parts Amount (suspense)';
COMMENT ON COLUMN cdk_work_in_process.wip_opened_date IS '[D] WIP Opened Date';
COMMENT ON COLUMN cdk_work_in_process.wip_age_days IS '[I] WIP Age in Days';
COMMENT ON COLUMN cdk_work_in_process.wip_closed_date IS '[D] WIP Closed Date';
COMMENT ON COLUMN cdk_work_in_process.wip_gl_account IS '[I] WIP GL Suspense Account';
COMMENT ON COLUMN cdk_work_in_process.wip_department_suffix IS '[I] WIP Department/Cost-Centre Suffix';
COMMENT ON COLUMN cdk_work_in_process._rooftop_id IS '[D] which rooftop/store this extracted row belongs to';
COMMENT ON COLUMN cdk_work_in_process._extracted_at IS '[D] when this row was pulled from CDK by the extract harness';
COMMENT ON COLUMN cdk_work_in_process._source_route IS '[D] which of the three extract routes produced this row: fortellis | export | screen';
COMMENT ON COLUMN cdk_work_in_process._batch_id IS '[D] the extract run/batch identifier this row landed with';

